{
  "name": "archive_file_sorter",
  "request_shape": "Go through the folder ~/Documents/Archive and all its subfolders and sort every file into one of these categories: invoices, contracts, personal letters, manuals, other. Give me a report listing each file under its category, and make sure no file is missed.",
  "inputs": [],
  "steps": [
    {
      "id": "s1",
      "kind": "list",
      "source": "files",
      "filter": "path=~/Documents/Archive recursive=true"
    },
    {
      "id": "s2",
      "kind": "batch",
      "size": 50
    },
    {
      "id": "s3",
      "kind": "loop_over_items",
      "over": "s2",
      "steps": [
        {
          "id": "s4",
          "kind": "classify",
          "enum": ["invoices", "contracts", "personal letters", "manuals", "other"],
          "question": "Classify this file into exactly one of the following categories based on its content and name: invoices, contracts, personal letters, manuals, other."
        }
      ]
    },
    {
      "id": "s5",
      "kind": "write",
      "instruction": "Generate a report listing each file under its assigned category. Format as: Category: [Name], File: [Path].",
      "max_words": 2000
    },
    {
      "id": "s6",
      "kind": "check_coverage",
      "rule": "Every file from input s1 must appear exactly once in the output of s5 grouped by category."
    }
  ],
  "output": "s5"
}

{
  "name": "process_morning_inbox",
  "request_shape": "Process my morning inbox: triage each new message since yesterday evening, draft a reply for every message that needs one, and send me a notification listing the rest.",
  "inputs": [],
  "steps": [
    {
      "id": "fetch_messages",
      "kind": "list",
      "source": "mail",
      "filter": "since yesterday evening"
    },
    {
      "id": "classify_messages",
      "kind": "loop_over_items",
      "over": "fetch_messages",
      "steps": [
        {
          "id": "classify_action",
          "kind": "classify",
          "enum": ["reply_needed", "notification_only"],
          "question": "Does this email require a drafted reply?"
        }
      ],
      "output": "classified_messages"
    },
    {
      "id": "draft_replies",
      "kind": "loop_over_items",
      "over": "classified_messages",
      "steps": [
        {
          "id": "filter_reply_needed",
          "kind": "loop_over_items",
          "over": "classify_action",
          "steps": [
            {
              "id": "check_reply_needed",
              "kind": "check_coverage",
              "rule": "item.value == 'reply_needed'"
            }
          ],
          "output": "reply_items"
        },
        {
          "id": "write_reply",
          "kind": "write",
          "instruction": "Draft a polite reply for the email content provided.",
          "max_words": 100
        }
      ],
      "output": "drafted_replies"
    },
    {
      "id": "filter_notifications",
      "kind": "loop_over_items",
      "over": "classified_messages",
      "steps": [
        {
          "id": "check_notification_only",
          "kind": "check_coverage",
          "rule": "item.value == 'notification_only'"
        }
      ],
      "output": "notification_items"
    },
    {
      "id": "generate_notification",
      "kind": "write",
      "instruction": "Create a notification listing the subjects of emails that do not require a reply.",
      "max_words": 50
    },
    {
      "id": "verify_coverage",
      "kind": "check_coverage",
      "rule": "every input item from fetch_messages appears exactly once in either drafted_replies or notification_items"
    }
  ],
  "output": "notification"
}

{
  "name": "find_shared_free_slot",
  "request_shape": "Find a free one-hour slot next week that works for both Dana Reyes and Sam Okafor, and propose it to them.",
  "inputs": [],
  "steps": [
    {
      "id": "get_dana_calendar",
      "kind": "list",
      "source": "calendar",
      "filter": "owner=Dana Reyes AND date >= next_monday AND date <= next_sunday"
    },
    {
      "id": "get_sam_calendar",
      "kind": "list",
      "source": "calendar",
      "filter": "owner=Sam Okafor AND date >= next_monday AND date <= next_sunday"
    },
    {
      "id": "generate_candidate_slots",
      "kind": "list",
      "source": "calendar",
      "filter": "owner=system AND date >= next_monday AND date <= next_sunday AND duration=1h"
    },
    {
      "id": "batch_slots",
      "kind": "batch",
      "over": "generate_candidate_slots",
      "size": 1
    },
    {
      "id": "check_dana_free",
      "kind": "loop_over_items",
      "over": "batch_slots",
      "steps": [
        {
          "id": "check_dana_conflict",
          "kind": "check_coverage",
          "rule": "slot_start not in get_dana_calendar AND slot_end not in get_dana_calendar"
        }
      ],
      "output": "dana_free_slots"
    },
    {
      "id": "check_sam_free",
      "kind": "loop_over_items",
      "over": "dana_free_slots",
      "steps": [
        {
          "id": "check_sam_conflict",
          "kind": "check_coverage",
          "rule": "slot_start not in get_sam_calendar AND slot_end not in get_sam_calendar"
        }
      ],
      "output": "shared_free_slots"
    },
    {
      "id": "select_slot",
      "kind": "check_coverage",
      "rule": "select first item from shared_free_slots"
    },
    {
      "id": "draft_proposal",
      "kind": "write",
      "instruction": "Draft a polite message proposing the selected time slot to Dana Reyes and Sam Okafor.",
      "max_words": 50
    },
    {
      "id": "send_to_dana",
      "kind": "lookup_via_agent",
      "agent": "mail",
      "find": "send to Dana Reyes with subject 'Meeting Proposal'"
    },
    {
      "id": "send_to_sam",
      "kind": "lookup_via_agent",
      "agent": "mail",
      "find": "send to Sam Okafor with subject 'Meeting Proposal'"
    },
    {
      "id": "verify_delivery",
      "kind": "check_coverage",
      "rule": "send_to_dana and send_to_sam both completed"
    }
  ],
  "output": "verify_delivery"
}

{
  "name": "weekly_review_report",
  "request_shape": "Weekly review: list my to-dos due this week, my meetings this week, and the mail I have not answered yet, as one report.",
  "inputs": [],
  "steps": [
    {
      "id": "fetch_todos",
      "kind": "list",
      "source": "todos",
      "filter": "due_this_week"
    },
    {
      "id": "fetch_meetings",
      "kind": "list",
      "source": "calendar",
      "filter": "this_week"
    },
    {
      "id": "fetch_mail",
      "kind": "list",
      "source": "mail",
      "filter": "unread_or_unanswered"
    },
    {
      "id": "classify_todos",
      "kind": "classify",
      "over": "fetch_todos",
      "question": "What is the priority of this task?",
      "enum": ["high", "medium", "low"]
    },
    {
      "id": "classify_mail",
      "kind": "classify",
      "over": "fetch_mail",
      "question": "What is the urgency of this email?",
      "enum": ["urgent", "normal", "low"]
    },
    {
      "id": "draft_report",
      "kind": "write",
      "instruction": "Generate a weekly review report listing the provided to-dos with their priority, meetings, and unanswered emails with their urgency. Use clear headings for each section.",
      "max_words": 500
    },
    {
      "id": "check_coverage",
      "kind": "check_coverage",
      "rule": "Every item from fetch_todos, fetch_meetings, and fetch_mail must appear in the draft_report output exactly once."
    }
  ],
  "output": "draft_report"
}
